def classify_enclosed_rect(r, c, grid, border_color, bg_color):
    """Check if there's a horizontal run of bg_color at (r,c) that's enclosed by border_color."""
    h, w = len(grid), len(grid[0])

    # Find the width of consecutive bg_color starting at column c in row r
    width = 0
    while c + width < w and grid[r][c + width] == bg_color:
        width += 1

    if width <= 1:
        return None

    # Find the height: consecutive rows having at least 'width' background from column c
    height = 0
    for sr in range(r, h):
        count = 0
        while c + count < w and grid[sr][c + count] == bg_color:
            count += 1
        if count < width:
            break
        height += 1

    if height <= 1:
        return None

    rect_end_r = r + height - 1
    rect_end_c = c + width - 1

    # Check top edge
    for cc in range(c, c + width):
        if grid[r][cc] != border_color:
            return None

    # Check bottom edge
    for cc in range(c, c + width):
        if grid[rect_end_r][cc] != border_color:
            return None

    # Check left edge
    for rr in range(r, r + height):
        if grid[rr][c] != border_color:
            return None

    # Check right edge
    for rr in range(r, r + height):
        if grid[rr][c + width - 1] != border_color:
            return None

    return (r, c, height, width)

